function useMe() {
  const [me, setMe] = useState<Me | null | undefined>();
  useEffect(() => { api<Me>("/api/v1/me").then(setMe).catch(() => setMe(null)); }, []);
  return me;
}

function Brand({ compact = false }: { compact?: boolean }) {
  return <div className="flex items-center gap-2.5 font-semibold tracking-[-0.03em]"><span className="grid size-7 place-items-center rounded-lg bg-primary text-primary-foreground"><Sparkles className="size-3.5" /></span>{!compact && <span>Knowledge</span>}</div>;
}

function AuthShell({ children, title, subtitle }: { children: ReactNode; title: string; subtitle: string }) {
  return <main className="grid min-h-full grid-cols-1 bg-background lg:grid-cols-[1.1fr_.9fr]">
    <section className="relative hidden overflow-hidden border-r border-border bg-foreground p-12 text-background lg:flex lg:flex-col">
      <Brand />
      <div className="my-auto max-w-lg"><Badge className="mb-6 border-white/15 bg-white/10 text-white/70">Markdown-first · Self-hosted</Badge><h2 className="text-5xl font-semibold leading-[1.05] tracking-[-.06em]">让知识可写、可连、<br />也可被 AI 使用。</h2><p className="mt-6 max-w-md text-base leading-7 text-white/55">私人笔记、协作工作区、公开文档与 MCP 大脑，在同一个可控的数据底座上。</p></div>
      <p className="text-xs text-white/40">数据属于你。Markdown 永远可迁移。</p>
      <div className="absolute -right-24 top-1/3 size-80 rounded-full bg-white/[.04] blur-3xl" />
    </section>
    <section className="flex min-h-screen items-center justify-center p-6"><div className="w-full max-w-[390px]"><div className="mb-10 lg:hidden"><Brand /></div><h1 className="text-3xl font-semibold tracking-[-.045em]">{title}</h1><p className="mt-2 text-sm text-muted-foreground">{subtitle}</p>{children}</div></section>
  </main>;
}

function Login() {
  const [email, setEmail] = useState(""); const [password, setPassword] = useState(""); const [err, setErr] = useState(""); const [busy, setBusy] = useState(false);
  async function submit(e: FormEvent) { e.preventDefault(); setErr(""); setBusy(true); try { await api("/api/v1/auth/login", { method: "POST", body: JSON.stringify({ email, password }) }); window.location.assign("/app"); } catch (x) { setErr((x as Error).message); setBusy(false); } }
  return <AuthShell title="欢迎回来" subtitle="登录后继续整理你的知识库。"><form className="mt-8 space-y-5" onSubmit={submit}><div className="space-y-2"><label className="text-sm font-medium">邮箱</label><Input type="email" autoFocus autoComplete="email" value={email} onChange={e => setEmail(e.target.value)} placeholder="name@example.com" /></div><div className="space-y-2"><label className="text-sm font-medium">密码</label><Input type="password" autoComplete="current-password" value={password} onChange={e => setPassword(e.target.value)} placeholder="输入密码" /></div>{err && <p className="rounded-lg bg-destructive/10 px-3 py-2 text-sm text-destructive">{err}</p>}<Button type="submit" className="w-full" disabled={busy}>{busy ? "正在登录…" : "登录"}</Button><p className="text-center text-sm"><Link className="text-muted-foreground underline underline-offset-4" to="/forgot-password">忘记密码？</Link></p><p className="text-center text-sm text-muted-foreground">还没有账号？ <Link className="font-medium text-foreground underline underline-offset-4" to="/register">创建账号</Link></p></form></AuthShell>;
}

function ForgotPassword(){const[email,setEmail]=useState("");const[done,setDone]=useState(false);return <AuthShell title="找回密码" subtitle="输入邮箱，我们会发送一小时有效的重置链接。">{done?<div className="mt-8 rounded-xl border bg-muted/30 p-5 text-sm">如果邮箱存在，重置说明已经发送。<Link className="mt-4 block underline" to="/login">返回登录</Link></div>:<form className="mt-8 space-y-4" onSubmit={async e=>{e.preventDefault();await api('/api/v1/auth/forgot-password',{method:'POST',body:JSON.stringify({email})});setDone(true)}}><Input type="email" required value={email} onChange={e=>setEmail(e.target.value)} placeholder="name@example.com"/><Button className="w-full">发送重置邮件</Button></form>}</AuthShell>}
function ResetPassword(){
  const token=new URLSearchParams(location.search).get("token")??""; const[password,setPassword]=useState(""); const[message,setMessage]=useState("");
  async function submit(e:FormEvent){e.preventDefault();try{await api("/api/v1/auth/reset-password",{method:"POST",body:JSON.stringify({token,password})});setMessage("密码已更新，请返回登录。");}catch(x){setMessage((x as Error).message);}}
  return <AuthShell title="设置新密码" subtitle="新密码至少 10 位，并同时包含字母和数字。"><form className="mt-8 space-y-4" onSubmit={submit}><Input type="password" value={password} onChange={e=>setPassword(e.target.value)} required/><Button className="w-full">更新密码</Button>{message&&<p className="text-sm">{message}</p>}<Link className="block text-center text-sm underline" to="/login">返回登录</Link></form></AuthShell>;
}
function VerifyEmail(){const token=new URLSearchParams(location.search).get('token')??'';const[status,setStatus]=useState('正在验证邮箱…');useEffect(()=>{api('/api/v1/auth/verify-email',{method:'POST',body:JSON.stringify({token})}).then(()=>location.assign('/app')).catch(e=>setStatus(e.message))},[]);return <AuthShell title="验证邮箱" subtitle="验证完成后即可使用知识库。"><p className="mt-8 rounded-xl border p-5 text-sm">{status}</p></AuthShell>}

function Register() {
  const [first, setFirst] = useState(false); const [busy, setBusy] = useState(false); const [err, setErr] = useState(""); const [form, setForm] = useState({ email: "", password: "", handle: "", displayName: "", registrationCode: "" });
  useEffect(() => { api<{ empty: boolean }>("/api/v1/meta").then(x => setFirst(x.empty)); }, []);
  const field = (key: keyof typeof form) => (e: React.ChangeEvent<HTMLInputElement>) => setForm({ ...form, [key]: e.target.value });
  async function submit(e: FormEvent) { e.preventDefault(); setBusy(true); setErr(""); try { const result=await api<{requiresVerification?:boolean;mailSent?:boolean;developmentToken?:string}>("/api/v1/auth/register", { method: "POST", body: JSON.stringify(form) }); if(result.requiresVerification){setErr(result.mailSent?'验证邮件已发送，请验证后登录。':`SMTP 未配置。开发验证地址：/verify-email?token=${result.developmentToken}`);setBusy(false)}else window.location.assign("/app"); } catch (x) { setErr((x as Error).message); setBusy(false); } }
  return <AuthShell title="创建账号" subtitle={first ? "首个账号将成为实例管理员。" : "从一个默认的个人工作区开始。"}><form className="mt-8 space-y-4" onSubmit={submit}><div className="grid grid-cols-2 gap-3"><div className="space-y-2"><label className="text-sm font-medium">显示名</label><Input value={form.displayName} onChange={field("displayName")} placeholder="你的名字" /></div><div className="space-y-2"><label className="text-sm font-medium">Handle</label><Input value={form.handle} onChange={field("handle")} placeholder="username" /></div></div><div className="space-y-2"><label className="text-sm font-medium">邮箱</label><Input type="email" value={form.email} onChange={field("email")} placeholder="name@example.com" /></div><div className="space-y-2"><label className="text-sm font-medium">密码</label><Input type="password" value={form.password} onChange={field("password")} placeholder="至少 10 位，含字母和数字" /></div>{!first && <div className="space-y-2"><label className="text-sm font-medium">注册码 <span className="font-normal text-muted-foreground">（关闭开放注册时必填）</span></label><Input value={form.registrationCode} onChange={field("registrationCode")} placeholder="XXXX-XXXX-XXXX-XXXX-XXXX" /></div>}{err && <p className="rounded-lg bg-destructive/10 px-3 py-2 text-sm text-destructive">{err}</p>}<Button className="w-full" disabled={busy}>{busy ? "正在创建…" : "创建账号"}</Button><p className="text-center text-sm text-muted-foreground">已有账号？ <Link className="font-medium text-foreground underline underline-offset-4" to="/login">返回登录</Link></p></form></AuthShell>;
}

type Ws = { id: string; name: string; kind: string; role: string; frozen?: boolean };
type Nb = { id: string; title: string; defaultAiIndex?: boolean; visibility?: "open"|"private"|"restricted"; createdBy?:string };
type FolderDto = { id: string; title: string; parentId: string | null };
type TreeNote = { id: string; title: string; folderId: string | null };
type NoteDto = { id: string; title: string; bodyMd: string; version: number; aiIndex: boolean; published: boolean; canEdit: boolean };
type Att = { id: string; filename: string; mime: string; bytes: number; url: string };
type CreateKind = "workspace" | "notebook" | "folder" | null;
type ShareDto = { id: string; token: string; hasPassword: boolean; expiresAt: string | null; status: string; createdAt: string };

function CreateDialog({ kind, onOpenChange, onSubmit }: { kind: CreateKind; onOpenChange: (v: boolean) => void; onSubmit: (name: string) => Promise<void> }) {
  const [name, setName] = useState(""); const [busy, setBusy] = useState(false);
  const names = kind === "workspace" ? ["新建工作区", "适合家庭、项目组或小团队协作。"] : kind === "notebook" ? ["新建笔记本", "笔记本是内容与权限的主要边界。"] : ["新建文件夹", "把相关笔记整理在一起。"];
  return <Dialog open={!!kind} onOpenChange={onOpenChange}><DialogContent><DialogHeader><DialogTitle>{names[0]}</DialogTitle><DialogDescription>{names[1]}</DialogDescription></DialogHeader><form className="space-y-4" onSubmit={async e => { e.preventDefault(); if (!name.trim()) return; setBusy(true); await onSubmit(name.trim()); setBusy(false); setName(""); onOpenChange(false); }}><Input autoFocus value={name} onChange={e => setName(e.target.value)} placeholder="输入名称" /><div className="flex justify-end gap-2"><Button type="button" variant="ghost" onClick={() => onOpenChange(false)}>取消</Button><Button disabled={busy || !name.trim()}>{busy ? "创建中…" : "创建"}</Button></div></form></DialogContent></Dialog>;
}

function ShareDialog({ note, open, onOpenChange }: { note: NoteDto | null; open: boolean; onOpenChange: (v: boolean) => void }) {
  const [shares, setShares] = useState<ShareDto[]>([]); const [password, setPassword] = useState(""); const [days, setDays] = useState<string>("never"); const [busy, setBusy] = useState(false); const [copied, setCopied] = useState("");
  const load = () => note && api<{ shares: ShareDto[] }>(`/api/v1/notes/${note.id}/shares`).then(d => setShares(d.shares));
  useEffect(() => { if (open) void load(); }, [open, note?.id]);
  const url = (s: ShareDto) => `${location.origin}/p/${s.token}`;
  async function copy(s: ShareDto) { await navigator.clipboard.writeText(url(s)); setCopied(s.id); setTimeout(() => setCopied(""), 1200); }
  return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="max-w-xl"><DialogHeader><DialogTitle className="flex items-center gap-2"><Share2 className="size-5" />分享《{note?.title}》</DialogTitle><DialogDescription>每条链接相互独立，可以设置密码、有效期或单独撤销。</DialogDescription></DialogHeader><div className="rounded-xl border border-border bg-muted/30 p-4"><div className="grid gap-3 sm:grid-cols-[1fr_150px_auto]"><Input type="password" value={password} onChange={e => setPassword(e.target.value)} placeholder="访问密码（可选）" /><select className="h-9 rounded-lg border border-input bg-background px-3 text-sm outline-none" value={days} onChange={e => setDays(e.target.value)}><option value="never">永不过期</option><option value="7">7 天</option><option value="30">30 天</option><option value="90">90 天</option></select><Button disabled={busy} onClick={async () => { if (!note) return; setBusy(true); const s = await api<ShareDto>(`/api/v1/notes/${note.id}/shares`, { method: "POST", body: JSON.stringify({ password: password || undefined, expiresInDays: days === "never" ? null : Number(days) }) }); setShares(v => [s, ...v]); setPassword(""); setBusy(false); await copy(s); }}>{busy ? "生成中…" : "生成并复制"}</Button></div></div><div className="max-h-72 space-y-2 overflow-auto">{shares.length === 0 ? <div className="py-10 text-center text-sm text-muted-foreground">还没有分享链接。</div> : shares.map(s => <div key={s.id} className="flex items-center gap-3 rounded-xl border border-border p-3"><span className={cn("grid size-9 place-items-center rounded-lg", s.status === "active" ? "bg-primary text-primary-foreground" : "bg-muted text-muted-foreground")}>{s.hasPassword ? <Lock className="size-4" /> : <Link2 className="size-4" />}</span><div className="min-w-0 flex-1"><p className="truncate font-mono text-xs">{url(s)}</p><p className="mt-1 text-[11px] text-muted-foreground">{s.status === "revoked" ? "已撤销" : s.expiresAt ? `到期 ${new Date(s.expiresAt).toLocaleDateString()}` : "永不过期"}{s.hasPassword ? " · 有密码" : " · 无密码"}</p></div>{s.status === "active" && <><Tooltip content="复制链接"><Button variant="ghost" size="icon" onClick={() => void copy(s)}>{copied === s.id ? <Check /> : <Copy />}</Button></Tooltip><Tooltip content="撤销链接"><Button variant="ghost" size="icon" className="text-destructive" onClick={async () => { await api(`/api/v1/shares/${s.id}`, { method: "DELETE" }); void load(); }}><Trash2 /></Button></Tooltip></>}</div>)}</div></DialogContent></Dialog>;
}

function VersionDialog({note,open,onOpenChange,onRestored}:{note:NoteDto|null;open:boolean;onOpenChange:(v:boolean)=>void;onRestored:(n:NoteDto)=>void}){const[versions,setVersions]=useState<Array<{id:string;version:number;title:string;bodyMd:string;source:string;createdAt:string}>>([]);const load=()=>note&&api<{versions:typeof versions}>(`/api/v1/notes/${note.id}/versions`).then(d=>setVersions(d.versions));useEffect(()=>{if(open)void load()},[open,note?.id]);return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="max-w-2xl"><DialogHeader><DialogTitle>版本历史</DialogTitle><DialogDescription>每次保存、AI 接受、纠错接受和恢复都会留下版本。</DialogDescription></DialogHeader><div className="max-h-[60vh] space-y-2 overflow-auto">{versions.map(v=><div key={v.id} className="flex items-center gap-3 rounded-xl border p-4"><div className="flex-1"><p className="text-sm font-medium">v{v.version} · {v.title}</p><p className="text-xs text-muted-foreground">{v.source} · {new Date(v.createdAt).toLocaleString()}</p></div><Button variant="outline" size="sm" onClick={async()=>{if(!note)return;const n=await api<NoteDto>(`/api/v1/notes/${note.id}/versions/${v.version}/restore`,{method:"POST"});onRestored(n);void load()}}><RotateCcw/>恢复为新版本</Button></div>)}</div></DialogContent></Dialog>}

function ReviewDialog({ note, open, onOpenChange }: { note: NoteDto | null; open: boolean; onOpenChange: (v:boolean)=>void }) { const [data,setData]=useState<{comments:Array<{id:string;body:string;guestName?:string}>;corrections:Array<{id:string;originalExcerpt:string;suggested:string;comment?:string;guestName?:string}>}>({comments:[],corrections:[]}); const load=()=>note&&api<typeof data>(`/api/v1/notes/${note.id}/interactions`).then(setData); useEffect(()=>{if(open)void load()},[open,note?.id]); return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="max-w-2xl"><DialogHeader><DialogTitle>互动审核</DialogTitle><DialogDescription>审核访客评论和纠错建议；接受纠错会产生一个新版本。</DialogDescription></DialogHeader><Tabs.Root defaultValue="comments"><Tabs.List className="mb-3 inline-flex rounded-lg bg-muted p-1"><Tabs.Trigger value="comments" className="rounded-md px-3 py-1.5 text-sm data-[state=active]:bg-background">评论 {data.comments.length}</Tabs.Trigger><Tabs.Trigger value="fixes" className="rounded-md px-3 py-1.5 text-sm data-[state=active]:bg-background">纠错 {data.corrections.length}</Tabs.Trigger></Tabs.List><Tabs.Content value="comments" className="max-h-96 space-y-2 overflow-auto">{data.comments.length===0?<p className="py-10 text-center text-sm text-muted-foreground">没有待审评论。</p>:data.comments.map(c=><div key={c.id} className="rounded-xl border p-4"><p className="text-xs text-muted-foreground">{c.guestName??"访客"}</p><p className="my-3 whitespace-pre-wrap text-sm">{c.body}</p><div className="flex justify-end gap-2"><Button size="sm" variant="ghost" onClick={async()=>{await api(`/api/v1/comments/${c.id}/review`,{method:"PATCH",body:JSON.stringify({status:"rejected"})});void load()}}>拒绝</Button><Button size="sm" onClick={async()=>{await api(`/api/v1/comments/${c.id}/review`,{method:"PATCH",body:JSON.stringify({status:"visible"})});void load()}}>通过</Button></div></div>)}</Tabs.Content><Tabs.Content value="fixes" className="max-h-96 space-y-2 overflow-auto">{data.corrections.length===0?<p className="py-10 text-center text-sm text-muted-foreground">没有待审纠错。</p>:data.corrections.map(f=><div key={f.id} className="rounded-xl border p-4"><div className="grid gap-3 sm:grid-cols-2"><div><p className="mb-1 text-xs text-muted-foreground">原文</p><p className="rounded-lg bg-destructive/5 p-3 text-sm">{f.originalExcerpt}</p></div><div><p className="mb-1 text-xs text-muted-foreground">建议</p><p className="rounded-lg bg-green-500/5 p-3 text-sm">{f.suggested}</p></div></div>{f.comment&&<p className="mt-3 text-sm text-muted-foreground">{f.comment}</p>}<div className="mt-3 flex justify-end gap-2"><Button size="sm" variant="ghost" onClick={async()=>{await api(`/api/v1/corrections/${f.id}/review`,{method:"PATCH",body:JSON.stringify({action:"reject"})});void load()}}>拒绝</Button><Button size="sm" onClick={async()=>{await api(`/api/v1/corrections/${f.id}/review`,{method:"PATCH",body:JSON.stringify({action:"accept"})});void load()}}>接受并应用</Button></div></div>)}</Tabs.Content></Tabs.Root></DialogContent></Dialog>; }

function NotebookAccessDialog({notebook,workspaceId,open,onOpenChange,onSaved}:{notebook:Nb|undefined;workspaceId:string|undefined;open:boolean;onOpenChange:(v:boolean)=>void;onSaved:()=>void}){const[members,setMembers]=useState<Array<{userId:string;displayName:string;handle:string;role:string}>>([]);const[allowed,setAllowed]=useState<Record<string,"view"|"edit">>({});useEffect(()=>{if(!open||!notebook||!workspaceId)return;Promise.all([api<{members:Array<{userId:string;displayName:string;handle:string;role:string}>}>(`/api/v1/workspaces/${workspaceId}/members`),api<{members:Array<{userId:string;role:"view"|"edit"}>}>(`/api/v1/notebooks/${notebook.id}/members`)]).then(([ws,acl])=>{setMembers(ws.members.filter(m=>m.role!=="owner"));setAllowed(Object.fromEntries(acl.members.map(m=>[m.userId,m.role])));})},[open,notebook?.id,workspaceId]);if(!notebook)return null;return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent><DialogHeader><DialogTitle>笔记本访问权限</DialogTitle><DialogDescription>开放：全体成员；私密：仅创建者；指定成员：只允许白名单。</DialogDescription></DialogHeader><select className="h-9 rounded-lg border bg-background px-3" value={notebook.visibility??"open"} onChange={async e=>{await api(`/api/v1/notebooks/${notebook.id}`,{method:"PATCH",body:JSON.stringify({visibility:e.target.value})});onSaved()}}><option value="open">全体成员</option><option value="private">仅我可见</option><option value="restricted">指定成员</option></select>{notebook.visibility==="restricted"&&<div className="max-h-72 space-y-2 overflow-auto">{members.map(m=><label key={m.userId} className="flex items-center gap-3 rounded-lg border p-3"><input type="checkbox" checked={!!allowed[m.userId]} onChange={e=>setAllowed(v=>{const n={...v};if(e.target.checked)n[m.userId]="view";else delete n[m.userId];return n})}/><span className="flex-1 text-sm">{m.displayName} <small className="text-muted-foreground">@{m.handle}</small></span>{allowed[m.userId]&&<select value={allowed[m.userId]} onChange={e=>setAllowed(v=>({...v,[m.userId]:e.target.value as "view"|"edit"}))}><option value="view">只读</option><option value="edit">可编辑</option></select>}</label>)}</div>}<Button onClick={async()=>{await api(`/api/v1/notebooks/${notebook.id}/members`,{method:"PUT",body:JSON.stringify({members:Object.entries(allowed).map(([userId,role])=>({userId,role}))})});onOpenChange(false);onSaved()}}>保存权限</Button></DialogContent></Dialog>}

function Workspace() {
  const me = useMe(); const nav = useNavigate(); const { wsId, noteId } = useParams();
  const [spaces, setSpaces] = useState<Ws[]>([]); const [nbs, setNbs] = useState<Nb[]>([]); const [nbId, setNbId] = useState<string>();
  const [folders, setFolders] = useState<FolderDto[]>([]); const [activeFolder, setActiveFolder] = useState<string | null>(null); const [tree, setTree] = useState<TreeNote[]>([]);
  const [note, setNote] = useState<NoteDto | null>(null); const noteRef = useRef<NoteDto | null>(null); const saveTimer = useRef<number | null>(null); const [status, setStatus] = useState("就绪");
  const [search, setSearch] = useState(""); const [hits, setHits] = useState<TreeNote[]>([]); const [backlinks, setBacklinks] = useState<Array<{ id: string; title: string; snippet: string }>>([]); const [atts, setAtts] = useState<Att[]>([]); const [showBacklinks, setShowBacklinks] = useState(false); const [create, setCreate] = useState<CreateKind>(null); const [confirmDelete, setConfirmDelete] = useState(false); const [showShare, setShowShare] = useState(false); const [showReview, setShowReview] = useState(false); const [showVersions,setShowVersions]=useState(false);const[showAiWrite,setShowAiWrite]=useState(false);const[showAsk,setShowAsk]=useState(false); const [showNotebookAccess,setShowNotebookAccess]=useState(false); const [site, setSite] = useState<{ published: boolean; slug: string } | null>(null);
  const activeWs = spaces.find(x => x.id === wsId); const activeNb = nbs.find(x => x.id === nbId);

  useEffect(() => { if (me === null) nav("/login"); }, [me, nav]);
  useEffect(() => { api<{ workspaces: Ws[] }>("/api/v1/workspaces").then(d => { setSpaces(d.workspaces); if (!wsId && me?.personalWorkspaceId) nav(`/w/${me.personalWorkspaceId}`, { replace: true }); }); }, [me, wsId, nav]);
  useEffect(() => { if (!wsId) return; api<{ notebooks: Nb[] }>(`/api/v1/workspaces/${wsId}/notebooks`).then(d => { setNbs(d.notebooks); setNbId(d.notebooks[0]?.id); }); }, [wsId]);
  async function refreshTree(id = nbId) { if (!id) return; const d = await api<{ folders: FolderDto[]; notes: TreeNote[] }>(`/api/v1/notebooks/${id}/tree`); setFolders(d.folders); setTree(d.notes); }
  useEffect(() => { void refreshTree(nbId); setActiveFolder(null); if (nbId) api<{ published: boolean; slug: string }>(`/api/v1/notebooks/${nbId}/site`).then(setSite).catch(() => setSite(null)); }, [nbId]);
  useEffect(() => { if (!noteId) { setNote(null); setAtts([]); return; } api<NoteDto>(`/api/v1/notes/${noteId}`).then(loaded => { setNote(loaded); noteRef.current = loaded; setStatus(`已保存 · v${loaded.version}`); }); api<{ items: typeof backlinks }>(`/api/v1/notes/${noteId}/backlinks`).then(d => setBacklinks(d.items)); api<{ attachments: Att[] }>(`/api/v1/notes/${noteId}/attachments`).then(d => setAtts(d.attachments)).catch(() => setAtts([])); }, [noteId]);
  useEffect(() => { noteRef.current = note; }, [note]);

  async function save(snapshot?: NoteDto) { const current = snapshot ?? noteRef.current; if (!current?.canEdit) return; if (saveTimer.current) clearTimeout(saveTimer.current); setStatus("保存中…"); try { const saved = await api<NoteDto>(`/api/v1/notes/${current.id}`, { method: "PATCH", body: JSON.stringify({ expectedVersion: current.version, title: current.title, bodyMd: current.bodyMd, aiIndex: current.aiIndex, published: current.published }) }); noteRef.current = saved; setNote(live => live?.id === saved.id && live.bodyMd !== current.bodyMd ? { ...live, version: saved.version } : saved); setTree(t => t.map(n => n.id === saved.id ? { ...n, title: saved.title } : n)); setStatus(`已保存 · v${saved.version}`); } catch (x) { setStatus((x as Error).message); } }
  function changeNote(patch: Partial<NoteDto>, instant = false) { if (!note) return; const next = { ...note, ...patch }; setNote(next); noteRef.current = next; setStatus("未保存"); if (saveTimer.current) clearTimeout(saveTimer.current); saveTimer.current = window.setTimeout(() => void save(next), instant ? 0 : 850); }
  async function createNote() { if (!nbId || !wsId) return; const n = await api<{ id: string }>("/api/v1/notes", { method: "POST", body: JSON.stringify({ notebookId: nbId, folderId: activeFolder }) }); await refreshTree(); nav(`/w/${wsId}/n/${n.id}`); }
  async function createNamed(kind: Exclude<CreateKind, null>, name: string) { if (kind === "workspace") { const d = await api<{ workspace: Ws }>("/api/v1/workspaces", { method: "POST", body: JSON.stringify({ name }) }); window.location.assign(`/w/${d.workspace.id}`); } else if (kind === "notebook" && wsId) { const n = await api<Nb>(`/api/v1/workspaces/${wsId}/notebooks`, { method: "POST", body: JSON.stringify({ title: name, visibility: "open" }) }); setNbs(v => [...v, n]); setNbId(n.id); } else if (kind === "folder" && nbId) { await api("/api/v1/folders", { method: "POST", body: JSON.stringify({ notebookId: nbId, parentId: activeFolder, title: name }) }); await refreshTree(); } }
  async function importIntoNotebook(files: FileList) { if (!nbId) return; setStatus("导入中…"); try { const payload: Array<{ path: string; content: string }> = []; for (const file of Array.from(files)) payload.push(...(/\.zip$/i.test(file.name) ? await readMarkdownZip(file) : [{ path: file.name, content: await file.text() }])); if (!payload.length) return setStatus("没有可导入的 Markdown"); if (payload.length > 500) return setStatus(`一次最多导入 500 篇，这次有 ${payload.length} 篇`); const d = await api<{ created: TreeNote[] }>(`/api/v1/notebooks/${nbId}/import-markdown`, { method: "POST", body: JSON.stringify({ files: payload }) }); await refreshTree(); setStatus(`已导入 ${d.created.length} 篇笔记`); } catch (e) { setStatus((e as Error).message); } }
  async function runSearch(value: string) { setSearch(value); if (!wsId || !value.trim()) return setHits([]); const d = await api<{ hits: TreeNote[] }>(`/api/v1/search?workspaceId=${wsId}&q=${encodeURIComponent(value)}`); setHits(d.hits); }
  async function deleteCurrent() { if (!note || !wsId) return; await api(`/api/v1/notes/${note.id}`, { method: "DELETE" }); await refreshTree(); setConfirmDelete(false); nav(`/w/${wsId}`); }
  function openWiki(title: string) { const target = tree.find(n => n.title.localeCompare(title, undefined, { sensitivity: "accent" }) === 0); if (target) nav(`/w/${wsId}/n/${target.id}`); }
  if (me === undefined) return <div className="grid h-full place-items-center"><Circle className="size-5 animate-pulse fill-current" /></div>;

  return <TooltipProvider delayDuration={300}><div className="flex h-full flex-col bg-background">
    <header className="flex h-14 shrink-0 items-center gap-3 border-b border-border px-3 md:px-4">
      <DropdownMenu><DropdownMenuTrigger asChild><Button variant="ghost" className="h-9 gap-2 px-2"><Brand compact /><span className="workspace-label max-w-40 truncate font-semibold">{activeWs?.name ?? "工作区"}</span><ChevronDown className="size-3.5 text-muted-foreground" /></Button></DropdownMenuTrigger><DropdownMenuContent align="start" className="w-64"><p className="px-2.5 py-2 text-xs font-medium text-muted-foreground">切换工作区</p>{spaces.map(s => <DropdownMenuItem key={s.id} onSelect={() => nav(`/w/${s.id}`)}><span className="grid size-7 place-items-center rounded-md bg-muted"><Users className="size-3.5" /></span><span className="flex-1 truncate">{s.name}</span>{s.id === wsId && <Check />}</DropdownMenuItem>)}<DropdownMenuSeparator /><DropdownMenuItem onSelect={() => setCreate("workspace")}><Plus />新建工作区</DropdownMenuItem></DropdownMenuContent></DropdownMenu>
      <Separator orientation="vertical" className="h-5" />
      <nav className="hidden items-center gap-1 md:flex"><Button variant="ghost" size="sm" className="text-muted-foreground"><BookOpen />笔记</Button><Button variant="ghost" size="sm" className="text-muted-foreground" onClick={()=>setShowAsk(true)}><Sparkles/>问知识库</Button><Button variant="ghost" size="sm" className="text-muted-foreground" onClick={() => nav("/")}><LayoutGrid />广场</Button></nav>
      <div className="relative mx-auto w-full max-w-md"><Search className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" /><Input className="h-9 bg-muted/70 pl-9 shadow-none" value={search} onChange={e => void runSearch(e.target.value)} placeholder="搜索这个工作区…" />{search && <Button variant="ghost" size="icon" className="absolute right-0 top-0 size-9" onClick={() => { setSearch(""); setHits([]); }}><X /></Button>}{hits.length > 0 && <div className="absolute left-0 right-0 top-11 z-40 rounded-xl border border-border bg-popover p-1.5 shadow-2xl">{hits.map(h => <button key={h.id} className="flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-left text-sm hover:bg-muted" onClick={() => { nav(`/w/${wsId}/n/${h.id}`); setSearch(""); setHits([]); }}><Search className="size-4 text-muted-foreground" /><span className="truncate">{h.title}</span></button>)}</div>}</div>
      <NotificationBell />
      <Tooltip content="外观"><Button variant="ghost" size="icon" onClick={() => nav("/settings/appearance")}><Paintbrush /></Button></Tooltip>
      <DropdownMenu><DropdownMenuTrigger asChild><Button variant="ghost" size="icon" className="rounded-full"><Avatar.Root className="grid size-8 place-items-center rounded-full bg-foreground text-xs font-semibold text-background"><Avatar.Fallback>{me?.displayName?.slice(0, 1) ?? "U"}</Avatar.Fallback></Avatar.Root></Button></DropdownMenuTrigger><DropdownMenuContent align="end" className="w-56"><div className="px-2.5 py-2"><p className="text-sm font-medium">{me?.displayName}</p><p className="truncate text-xs text-muted-foreground">{me?.email}</p>{me?.storage&&<div className="mt-2"><div className="mb-1 flex justify-between text-[10px] text-muted-foreground"><span>存储空间</span><span>{(me.storage.usedBytes/1048576).toFixed(1)} MB / {(me.storage.quotaBytes/1073741824).toFixed(1)} GB</span></div><div className="h-1.5 overflow-hidden rounded-full bg-muted"><div className="h-full rounded-full bg-primary" style={{width:`${Math.min(100,me.storage.usedBytes/me.storage.quotaBytes*100)}%`}}/></div></div>}</div><DropdownMenuSeparator /><DropdownMenuItem onSelect={() => nav(`/w/${wsId}/trash`)}><Archive />回收站</DropdownMenuItem><DropdownMenuItem onSelect={() => nav(`/w/${wsId}/members`)}><Users />成员管理</DropdownMenuItem><DropdownMenuItem onSelect={() => nav(`/w/${wsId}/manage`)}><Archive />备份与审计</DropdownMenuItem><DropdownMenuItem onSelect={() => nav(`/settings/integrations?workspace=${wsId}`)}><Bot />AI 与 MCP</DropdownMenuItem><DropdownMenuItem onSelect={() => nav("/settings/appearance")}><Settings />外观设置</DropdownMenuItem>{me?.instanceRole === "admin" && <DropdownMenuItem onSelect={() => nav("/admin")}><Settings />实例后台</DropdownMenuItem>}<DropdownMenuSeparator />{me?.status==="pending_deletion"?<DropdownMenuItem onSelect={async()=>{await api('/api/v1/account/cancel-deletion',{method:'POST'});location.reload()}}><RotateCcw/>撤销账号注销</DropdownMenuItem>:<DropdownMenuItem className="text-destructive" onSelect={async()=>{const password=prompt('请输入密码确认申请注销（7 天内可撤销）');if(!password)return;try{await api('/api/v1/account/request-deletion',{method:'POST',body:JSON.stringify({password})});location.assign('/login')}catch(e){alert((e as Error).message)}}}><Trash2/>申请注销账号</DropdownMenuItem>}<DropdownMenuItem className="text-destructive" onSelect={async () => { await api("/api/v1/auth/logout", { method: "POST" }); window.location.assign("/login"); }}><LogOut />退出登录</DropdownMenuItem></DropdownMenuContent></DropdownMenu>
    </header>

    <main className="app-grid grid min-h-0 flex-1">
      <aside className="notebook-panel flex min-h-0 flex-col border-r border-border bg-muted/35 p-2.5"><div className="flex h-10 items-center justify-between px-2"><span className="sidebar-copy text-[11px] font-semibold uppercase tracking-[.12em] text-muted-foreground">笔记本</span><Tooltip content="新建笔记本"><Button variant="ghost" size="icon" className="size-7" onClick={() => setCreate("notebook")}><Plus /></Button></Tooltip></div><ScrollArea className="flex-1"><div className="space-y-1">{nbs.map(n => <button key={n.id} onClick={() => setNbId(n.id)} className={cn("flex h-9 w-full items-center gap-2.5 rounded-lg px-2.5 text-left text-sm transition", n.id === nbId ? "bg-foreground text-background shadow-sm" : "text-muted-foreground hover:bg-muted hover:text-foreground")}><Notebook className="size-4 shrink-0" /><span className="sidebar-copy truncate">{n.title}</span></button>)}</div></ScrollArea><div className="border-t border-border pt-2"><button onClick={() => nav(`/w/${wsId}/trash`)} className="flex h-9 w-full items-center gap-2.5 rounded-lg px-2.5 text-sm text-muted-foreground hover:bg-muted hover:text-foreground"><Archive className="size-4" /><span className="sidebar-copy">回收站</span></button></div></aside>

      <aside className="tree-panel flex min-h-0 flex-col border-r border-border bg-background"><div className="flex h-14 items-center gap-2 border-b border-border px-3"><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold">{activeNb?.title ?? "笔记"}</p><p className="text-[11px] text-muted-foreground">{tree.length} 篇笔记 · {activeNb?.visibility==="private"?"私密":activeNb?.visibility==="restricted"?"指定成员":"全体成员"}</p></div><Tooltip content="访问权限"><Button variant="ghost" size="icon" className="size-8" onClick={()=>setShowNotebookAccess(true)}><Lock/></Button></Tooltip><Tooltip content="导入 Markdown 或 zip"><Button variant="ghost" size="icon" className="size-8" onClick={() => document.getElementById("import-md-input")?.click()}><Upload /></Button></Tooltip><input id="import-md-input" type="file" multiple accept=".md,.markdown,.zip,text/markdown,application/zip" className="hidden" onChange={e => { const files = e.target.files; e.target.value = ""; if (files?.length) void importIntoNotebook(files); }} /><Tooltip content="新建文件夹"><Button variant="ghost" size="icon" className="size-8" onClick={() => setCreate("folder")}><FolderPlus /></Button></Tooltip><Tooltip content="新建笔记"><Button size="icon" className="size-8" onClick={createNote}><FilePlus2 /></Button></Tooltip></div><ScrollArea className="flex-1"><div className="p-2.5"><button onClick={() => setActiveFolder(null)} className={cn("mb-1 flex h-9 w-full items-center gap-2 rounded-lg px-2.5 text-sm", activeFolder === null ? "bg-muted font-medium" : "text-muted-foreground hover:bg-muted/70")}><Folder className="size-4" />全部笔记</button>{folders.map(f => <button key={f.id} onClick={() => setActiveFolder(f.id)} className={cn("mb-1 flex h-9 w-full items-center gap-2 rounded-lg px-2.5 text-sm", activeFolder === f.id ? "bg-muted font-medium" : "text-muted-foreground hover:bg-muted/70")}><ChevronRight className="size-3.5" /><Folder className="size-4" /><span className="truncate">{f.title}</span></button>)}<Separator className="my-3" /><div className="space-y-0.5">{tree.filter(n => activeFolder === null || n.folderId === activeFolder).map(n => <Link key={n.id} to={`/w/${wsId}/n/${n.id}`} className={cn("group flex min-h-10 items-start gap-2.5 rounded-lg px-2.5 py-2 text-sm transition", n.id === noteId ? "bg-primary text-primary-foreground shadow-sm" : "hover:bg-muted")}><FilePlus2 className={cn("mt-0.5 size-3.5 shrink-0", n.id === noteId ? "text-primary-foreground/70" : "text-muted-foreground")} /><span className="line-clamp-2 leading-5">{n.title}</span></Link>)}</div></div></ScrollArea></aside>

      <section className="relative flex min-h-0 min-w-0 flex-col bg-background">{note ? <>
        <input id="note-attachment-input" className="hidden" type="file" onChange={async e=>{const f=e.target.files?.[0];if(!f||!note)return;const form=new FormData();form.append('file',f);const res=await fetch(`/api/v1/notes/${note.id}/attachments`,{method:'POST',body:form,credentials:'include'});const json=await res.json();if(!json.ok){setStatus(json.error.message);return}const a=json.data as Att;setAtts(v=>[...v,a]);changeNote({bodyMd:`${note.bodyMd}\n\n${a.mime.startsWith('image/')?'!':''}[${a.filename}](${a.url})`});e.target.value=''}} />
        <div className="flex h-14 shrink-0 items-center gap-2 border-b border-border px-4"><div className="flex min-w-0 items-center gap-1.5 text-xs text-muted-foreground"><span>{activeNb?.title}</span><ChevronRight className="size-3" /><span className="truncate text-foreground">{note.title || "未命名"}</span></div><div className="ml-auto flex items-center gap-1"><span className={cn("mr-2 hidden text-xs sm:block", status.startsWith("已保存") ? "text-muted-foreground" : "text-foreground")}>{status}</span><Button size="sm" onClick={() => setShowShare(true)}><Share2 /> <span className="hidden sm:inline">分享</span></Button><Tooltip content={note.aiIndex ? "AI 可读取此笔记" : "AI 无法读取此笔记"}><Button variant={note.aiIndex ? "secondary" : "ghost"} size="sm" onClick={() => changeNote({ aiIndex: !note.aiIndex }, true)}><Bot /> <span className="hidden sm:inline">AI 可读</span></Button></Tooltip><Tooltip content="反向链接"><Button variant={showBacklinks ? "secondary" : "ghost"} size="icon" onClick={() => setShowBacklinks(v => !v)}><PanelRight /></Button></Tooltip><DropdownMenu><DropdownMenuTrigger asChild><Button variant="ghost" size="icon"><MoreHorizontal /></Button></DropdownMenuTrigger><DropdownMenuContent align="end"><DropdownMenuItem onSelect={()=>setShowAiWrite(true)}><Sparkles/>AI 写作建议</DropdownMenuItem><DropdownMenuItem onSelect={() => setShowVersions(true)}><RotateCcw />版本历史</DropdownMenuItem><DropdownMenuItem onSelect={()=>document.getElementById('note-attachment-input')?.click()}><Paperclip />上传附件</DropdownMenuItem><DropdownMenuItem onSelect={() => setShowReview(true)}><Users />审核评论与纠错</DropdownMenuItem><DropdownMenuItem onSelect={() => setShowBacklinks(true)}><PanelRight />查看反向链接 <Badge className="ml-auto">{backlinks.length}</Badge></DropdownMenuItem><DropdownMenuItem onSelect={() => changeNote({ published: !note.published }, true)}><Globe2 />{note.published ? "从文档站隐藏此页" : "在文档站发布此页"}</DropdownMenuItem><DropdownMenuItem onSelect={async () => { if (!nbId) return; const next = !site?.published; const d = await api<{ published: boolean; slug: string }>(`/api/v1/notebooks/${nbId}/site`, { method: "PATCH", body: JSON.stringify({ published: next }) }); setSite(d); }}><Globe2 />{site?.published ? "下线文档站" : "发布笔记本为文档站"}</DropdownMenuItem>{site?.published && <DropdownMenuItem onSelect={() => window.open(site.slug, "_blank")}><ExternalLink />打开文档站</DropdownMenuItem>}<DropdownMenuSeparator /><DropdownMenuItem className="text-destructive" onSelect={() => setConfirmDelete(true)}><Trash2 />移到回收站</DropdownMenuItem></DropdownMenuContent></DropdownMenu></div></div>
        <div className="min-h-0 flex-1"><Tabs.Root defaultValue="split" className="flex h-full flex-col"><div className="flex items-center justify-between px-6 pt-6"><Tabs.List className="inline-flex rounded-lg bg-muted p-1"><Tabs.Trigger value="write" className="rounded-md px-3 py-1.5 text-xs font-medium text-muted-foreground data-[state=active]:bg-background data-[state=active]:text-foreground data-[state=active]:shadow-sm">编辑</Tabs.Trigger><Tabs.Trigger value="preview" className="rounded-md px-3 py-1.5 text-xs font-medium text-muted-foreground data-[state=active]:bg-background data-[state=active]:text-foreground data-[state=active]:shadow-sm">预览</Tabs.Trigger><Tabs.Trigger value="split" className="hidden rounded-md px-3 py-1.5 text-xs font-medium text-muted-foreground data-[state=active]:bg-background data-[state=active]:text-foreground data-[state=active]:shadow-sm sm:block">分栏</Tabs.Trigger></Tabs.List></div><div className="mx-auto flex min-h-0 w-full max-w-[1400px] flex-1 flex-col px-6 pb-6 pt-4"><input className="mb-4 w-full border-0 bg-transparent font-[var(--font-title)] text-3xl font-semibold tracking-[-.045em] outline-none placeholder:text-muted-foreground/40 md:text-4xl" value={note.title} onChange={e => changeNote({ title: e.target.value })} placeholder="无标题" /><Tabs.Content value="write" className="min-h-0 flex-1"><textarea className="editor-textarea h-full w-full resize-none border-0 bg-transparent font-mono text-sm leading-7 outline-none" value={note.bodyMd} onChange={e => changeNote({ bodyMd: e.target.value })} placeholder="开始写作，或输入 [[笔记标题]] 建立双链…" /></Tabs.Content><Tabs.Content value="preview" className="min-h-0 flex-1 overflow-auto"><div className="mx-auto max-w-3xl py-2"><MarkdownView source={note.bodyMd} onWiki={openWiki} /></div></Tabs.Content><Tabs.Content value="split" className="min-h-0 flex-1"><div className="grid h-full min-h-0 grid-cols-1 divide-x divide-border overflow-hidden rounded-xl border border-border md:grid-cols-2"><textarea className="editor-textarea h-full min-h-0 resize-none border-0 bg-muted/25 p-5 font-mono text-sm leading-7 outline-none" value={note.bodyMd} onChange={e => changeNote({ bodyMd: e.target.value })} placeholder="开始写作，或输入 [[笔记标题]] 建立双链…" /><ScrollArea className="h-full"><div className="p-6"><MarkdownView source={note.bodyMd} onWiki={openWiki} /></div></ScrollArea></div></Tabs.Content></div></Tabs.Root></div>
        {showBacklinks && <div className="absolute bottom-0 right-0 top-14 z-30 flex w-[340px] flex-col border-l border-border bg-background shadow-[-16px_0_40px_rgba(0,0,0,.05)]"><div className="flex h-14 items-center border-b border-border px-4"><div><p className="text-sm font-semibold">反向链接</p><p className="text-[11px] text-muted-foreground">{backlinks.length} 个页面提到了这里</p></div><Button className="ml-auto" variant="ghost" size="icon" onClick={() => setShowBacklinks(false)}><X /></Button></div><ScrollArea className="flex-1"><div className="space-y-2 p-3">{backlinks.length === 0 ? <div className="py-16 text-center"><PanelRight className="mx-auto mb-3 size-8 text-muted-foreground/40" /><p className="text-sm font-medium">还没有反向链接</p><p className="mt-1 text-xs text-muted-foreground">其他笔记链接到这里后会显示。</p></div> : backlinks.map(b => <Link key={b.id} to={`/w/${wsId}/n/${b.id}`} className="block rounded-xl border border-border p-3 hover:bg-muted"><p className="text-sm font-medium">{b.title}</p><p className="mt-1.5 line-clamp-3 text-xs leading-5 text-muted-foreground">{b.snippet}</p></Link>)}
          <Separator className="my-4" /><p className="mb-2 text-[11px] font-semibold uppercase tracking-[.12em] text-muted-foreground">附件 {atts.length > 0 && `· ${atts.length}`}</p>
          {atts.length === 0 ? <p className="pb-2 text-xs text-muted-foreground">还没有附件。用编辑器工具栏的回形针上传，正文里会插入链接。</p> : atts.map(a => <div key={a.id} className="flex items-center gap-2 rounded-xl border border-border p-2.5"><Paperclip className="size-3.5 shrink-0 text-muted-foreground" /><a href={a.url} target="_blank" rel="noreferrer" className="min-w-0 flex-1 truncate text-xs hover:underline">{a.filename}</a><span className="shrink-0 text-[11px] text-muted-foreground">{a.bytes < 1048576 ? `${Math.round(a.bytes / 1024)} KB` : `${(a.bytes / 1048576).toFixed(1)} MB`}</span>{note.canEdit && <Button variant="ghost" size="icon" className="size-7" onClick={async () => { if (!confirm(`删除附件《${a.filename}》？正文里的链接需要自己清理。`)) return; try { await api(`/api/v1/attachments/${a.id}`, { method: "DELETE" }); setAtts(v => v.filter(x => x.id !== a.id)); } catch (e) { setStatus((e as Error).message); } }}><Trash2 /></Button>}</div>)}</div></ScrollArea></div>}
      </> : <div className="grid h-full place-items-center p-8"><div className="max-w-sm text-center"><span className="mx-auto grid size-14 place-items-center rounded-2xl bg-muted"><Notebook className="size-6 text-muted-foreground" /></span><h2 className="mt-5 text-lg font-semibold tracking-tight">选择一篇笔记开始</h2><p className="mt-2 text-sm leading-6 text-muted-foreground">从左侧打开现有笔记，或者新建一篇内容。</p><Button className="mt-5" onClick={createNote}><FilePlus2 />新建笔记</Button></div></div>}</section>
    </main>
    <CreateDialog kind={create} onOpenChange={v => !v && setCreate(null)} onSubmit={name => createNamed(create!, name)} />
    <ShareDialog note={note} open={showShare} onOpenChange={setShowShare} />
    <NotebookAccessDialog notebook={activeNb} workspaceId={wsId} open={showNotebookAccess} onOpenChange={setShowNotebookAccess} onSaved={()=>wsId&&api<{notebooks:Nb[]}>(`/api/v1/workspaces/${wsId}/notebooks`).then(d=>{setNbs(d.notebooks);const fresh=d.notebooks.find(n=>n.id===nbId);if(!fresh)setNbId(d.notebooks[0]?.id)})} />
    <ReviewDialog note={note} open={showReview} onOpenChange={setShowReview} />
    <VersionDialog note={note} open={showVersions} onOpenChange={setShowVersions} onRestored={n=>{setNote(n);noteRef.current=n}} />
    <AiWriteDialog note={note} open={showAiWrite} onOpenChange={setShowAiWrite} onAccept={async(text,baseVersion)=>{if(!note)return;const saved=await api<NoteDto>(`/api/v1/notes/${note.id}`,{method:'PATCH',body:JSON.stringify({expectedVersion:baseVersion,title:note.title,bodyMd:text,aiIndex:note.aiIndex,published:note.published,source:'ai_accept'})});setNote(saved);noteRef.current=saved;setStatus(`已保存 · v${saved.version}`)}}/>
    <AskDialog open={showAsk} onOpenChange={setShowAsk} workspaceId={wsId} onOpenNote={id=>nav(`/w/${wsId}/n/${id}`)}/>
    <Dialog open={confirmDelete} onOpenChange={setConfirmDelete}><DialogContent><DialogHeader><DialogTitle>移到回收站？</DialogTitle><DialogDescription>《{note?.title}》将从笔记列表中消失，你可以稍后从回收站恢复。</DialogDescription></DialogHeader><div className="flex justify-end gap-2"><Button variant="ghost" onClick={() => setConfirmDelete(false)}>取消</Button><Button variant="destructive" onClick={deleteCurrent}><Trash2 />确认删除</Button></div></DialogContent></Dialog>
  </div></TooltipProvider>;
}

function PublicInteractions({ noteId, shareToken }: { noteId: string; shareToken: string }) { const [comments, setComments] = useState<Array<{id:string;body:string;author:string;createdAt:string}>>([]); const [body,setBody]=useState(""); const [name,setName]=useState(""); const [msg,setMsg]=useState(""); const load=()=>api<{comments:typeof comments}>(`/api/v1/public/notes/${noteId}/comments?shareToken=${shareToken}`).then(d=>setComments(d.comments)); useEffect(()=>{void load()},[noteId,shareToken]); return <section className="mx-auto mt-16 max-w-3xl border-t pt-10"><h2 className="text-xl font-semibold">评论</h2><div className="mt-5 space-y-4">{comments.length===0?<p className="text-sm text-muted-foreground">还没有公开评论。</p>:comments.map(c=><div key={c.id} className="rounded-xl bg-muted/50 p-4"><div className="flex items-center gap-2 text-xs text-muted-foreground"><b className="text-foreground">{c.author}</b><span>{new Date(c.createdAt).toLocaleString()}</span></div><p className="mt-2 whitespace-pre-wrap text-sm leading-6">{c.body}</p></div>)}</div><form className="mt-6 space-y-3" onSubmit={async e=>{e.preventDefault();setMsg("");try{const d=await api<{status:string}>(`/api/v1/public/notes/${noteId}/comments?shareToken=${shareToken}`,{method:"POST",body:JSON.stringify({body,guestName:name||undefined})});setBody("");setMsg(d.status==="pending"?"评论已提交，等待审核。":"评论已发布。");void load();}catch(x){setMsg((x as Error).message)}}}><Input value={name} onChange={e=>setName(e.target.value)} placeholder="访客昵称（登录用户可留空）" /><Textarea value={body} onChange={e=>setBody(e.target.value)} placeholder="写下评论…" maxLength={2000}/><div className="flex items-center gap-3"><Button disabled={!body.trim()}>发表评论</Button>{msg&&<span className="text-xs text-muted-foreground">{msg}</span>}</div></form></section>; }

function PublicShare() {
  const { token } = useParams(); const [data, setData] = useState<{ requiresPassword: boolean; noteId?: string; shareToken?: string; title: string; bodyMd?: string; updatedAt?: string; notebookTitle?: string; commentsEnabled?: boolean } | null>(null); const [password, setPassword] = useState(""); const [err, setErr] = useState("");
  const load = () => token && api<typeof data>(`/api/v1/public/shares/${token}`).then(setData).catch(e => setErr((e as Error).message)); useEffect(() => { void load(); }, [token]);
  if (err) return <PublicFrame><Empty icon={<Link2 />} title="分享不存在或已失效" text="链接可能已被撤销、过期，或者内容已删除。" /></PublicFrame>;
  if (!data) return <div className="grid h-full place-items-center"><Circle className="size-5 animate-pulse fill-current" /></div>;
  if (data.requiresPassword) return <PublicFrame><div className="mx-auto max-w-sm rounded-2xl border border-border p-7 text-center"><span className="mx-auto grid size-12 place-items-center rounded-xl bg-muted"><Lock className="size-5" /></span><h1 className="mt-4 text-xl font-semibold">此分享受密码保护</h1><p className="mt-2 text-sm text-muted-foreground">输入分享者提供的密码以继续阅读。</p><form className="mt-5 space-y-3" onSubmit={async e => { e.preventDefault(); setErr(""); try { await api(`/api/v1/public/shares/${token}/unlock`, { method: "POST", body: JSON.stringify({ password }) }); setData(null); void load(); } catch (x) { setErr((x as Error).message); } }}><Input autoFocus type="password" value={password} onChange={e => setPassword(e.target.value)} placeholder="访问密码" />{err && <p className="text-sm text-destructive">{err}</p>}<Button className="w-full">解锁内容</Button></form></div></PublicFrame>;
  return <PublicFrame><article className="mx-auto max-w-3xl"><div className="mb-10 border-b border-border pb-8"><Badge>{data.notebookTitle}</Badge><h1 className="mt-4 text-4xl font-semibold tracking-[-.055em] md:text-5xl">{data.title}</h1>{data.updatedAt && <p className="mt-4 text-xs text-muted-foreground">更新于 {new Date(data.updatedAt).toLocaleString()}</p>}</div><MarkdownView source={data.bodyMd ?? ""} /></article>{data.commentsEnabled&&data.noteId&&data.shareToken&&<PublicInteractions noteId={data.noteId} shareToken={data.shareToken}/>}</PublicFrame>;
}
function PublicFrame({ children }: { children: ReactNode }) { return <div className="min-h-full bg-background"><header className="flex h-14 items-center border-b border-border px-5"><Brand /><Badge className="ml-3">公开阅读</Badge></header><main className="px-5 py-10 md:py-16">{children}</main></div>; }

function PublicSite() {
  const { wsSlug, nbSlug } = useParams(); const [data, setData] = useState<{ workspace: string; notebook: string; accent: string | null; notes: Array<{ id: string; title: string; bodyMd: string; updatedAt: string }> } | null>(null); const [active, setActive] = useState<string>(); const [err, setErr] = useState("");
  useEffect(() => { api<typeof data>(`/api/v1/public/sites/${wsSlug}/${nbSlug}`).then(d => { setData(d); setActive(d?.notes[0]?.id); }).catch(e => setErr((e as Error).message)); }, [wsSlug, nbSlug]);
  if (err) return <PublicFrame><Empty icon={<Globe2 />} title="文档站尚未发布" text="此站点不存在，或者管理员已将其下线。" /></PublicFrame>;
  if (!data) return <div className="grid h-full place-items-center"><Circle className="size-5 animate-pulse fill-current" /></div>;
  const current = data.notes.find(n => n.id === active);
  return <div className="flex h-full flex-col" style={data.accent ? ({ "--primary": data.accent } as React.CSSProperties) : undefined}><header className="flex h-14 items-center border-b border-border px-4"><Brand /><Separator orientation="vertical" className="mx-4 h-5" /><span className="font-medium">{data.notebook}</span><span className="ml-auto text-xs text-muted-foreground">{data.workspace}</span></header><div className="grid min-h-0 flex-1 md:grid-cols-[260px_1fr]"><aside className="hidden min-h-0 border-r border-border bg-muted/30 md:block"><ScrollArea className="h-full"><div className="p-4"><p className="mb-3 text-[11px] font-semibold uppercase tracking-wider text-muted-foreground">目录</p>{data.notes.map(n => <button key={n.id} onClick={() => setActive(n.id)} className={cn("mb-1 w-full rounded-lg px-3 py-2.5 text-left text-sm", n.id === active ? "bg-primary text-primary-foreground" : "hover:bg-muted")}>{n.title}</button>)}</div></ScrollArea></aside><ScrollArea className="h-full"><main className="mx-auto max-w-3xl px-6 py-12"><h1 className="mb-10 text-4xl font-semibold tracking-[-.055em]">{current?.title ?? "暂无公开页面"}</h1>{current && <MarkdownView source={current.bodyMd} />}</main></ScrollArea></div></div>;
}

function Members() {
  const { wsId } = useParams(); const nav = useNavigate(); const [kind, setKind] = useState(""); const [ownerId,setOwnerId]=useState(""); const [members, setMembers] = useState<Array<{ userId: string; handle: string; displayName: string; email: string; role: string; joinedAt: string }>>([]); const [handle, setHandle] = useState(""); const [role, setRole] = useState("viewer"); const [invite, setInvite] = useState(""); const [msg, setMsg] = useState("");
  const load = () => wsId && api<{ kind: string; members: typeof members }>(`/api/v1/workspaces/${wsId}/members`).then(d => { setKind(d.kind); setMembers(d.members);setOwnerId(d.members.find(m=>m.role==='owner')?.userId??''); }); useEffect(() => { void load(); }, [wsId]);
  async function add() { if (!handle || !wsId) return; setMsg(""); try { await api(`/api/v1/workspaces/${wsId}/members`, { method: "POST", body: JSON.stringify({ handle, role }) }); setHandle(""); await load(); } catch (e) { setMsg((e as Error).message); } }
  async function makeInvite() { if (!wsId) return; const d = await api<{ url: string }>(`/api/v1/workspaces/${wsId}/invites`, { method: "POST", body: JSON.stringify({ role, expiresInDays: 7, maxUses: 1 }) }); const url = location.origin + d.url; setInvite(url); await navigator.clipboard.writeText(url); }
  return <PageShell title="成员管理" subtitle={kind === "personal" ? "个人工作区只能由你自己使用。请新建普通工作区进行协作。" : "添加成员、调整角色或生成一次性邀请链接。"} back={() => nav(`/w/${wsId}`)}>{kind !== "personal" && <div className="mb-6 rounded-xl border border-border bg-background p-4"><div className="grid gap-3 sm:grid-cols-[1fr_150px_auto_auto]"><Input value={handle} onChange={e => setHandle(e.target.value)} placeholder="输入用户 handle" /><select className="h-9 rounded-lg border bg-background px-3 text-sm" value={role} onChange={e => setRole(e.target.value)}><option value="viewer">Viewer</option><option value="editor">Editor</option><option value="admin">Admin</option></select><Button onClick={add}><Users />直接添加</Button><Button variant="outline" onClick={makeInvite}><Link2 />邀请链接</Button><Button variant="destructive" onClick={async()=>{if(!wsId)return;const name=prompt('输入完整工作区名称确认删除');if(!name)return;try{await api(`/api/v1/workspaces/${wsId}`,{method:'DELETE',body:JSON.stringify({confirmName:name})});location.assign('/app')}catch(e){setMsg((e as Error).message)}}}><Trash2/>删除工作区</Button></div>{invite && <div className="mt-3 flex items-center gap-2 rounded-lg bg-muted px-3 py-2 font-mono text-xs"><span className="min-w-0 flex-1 truncate">{invite}</span><Badge>已复制</Badge></div>}{msg && <p className="mt-2 text-sm text-destructive">{msg}</p>}</div>}<div className="overflow-hidden rounded-xl border bg-background">{members.map((m, i) => <div key={m.userId} className={cn("flex items-center gap-4 p-4", i && "border-t")}><Avatar.Root className="grid size-10 place-items-center rounded-full bg-foreground text-background"><Avatar.Fallback>{m.displayName.slice(0, 1)}</Avatar.Fallback></Avatar.Root><div className="min-w-0 flex-1"><p className="text-sm font-medium">{m.displayName} <span className="font-normal text-muted-foreground">@{m.handle}</span></p><p className="text-xs text-muted-foreground">{m.email}</p></div><Badge>{m.role}</Badge>{kind !== "personal" && m.role !== "owner" && <DropdownMenu><DropdownMenuTrigger asChild><Button variant="ghost" size="icon"><MoreHorizontal /></Button></DropdownMenuTrigger><DropdownMenuContent align="end">{m.userId!==ownerId&&<DropdownMenuItem onSelect={async()=>{if(!confirm(`把工作区 Owner 转让给 ${m.displayName}？`))return;await api(`/api/v1/workspaces/${wsId}/transfer`,{method:'POST',body:JSON.stringify({newOwnerUserId:m.userId})});void load()}}><Users/>转让 Owner</DropdownMenuItem>}{["admin","editor","viewer"].map(r => <DropdownMenuItem key={r} onSelect={async () => { await api(`/api/v1/workspaces/${wsId}/members/${m.userId}`, { method: "PATCH", body: JSON.stringify({ role: r }) }); void load(); }}>{r}{m.role === r && <Check className="ml-auto" />}</DropdownMenuItem>)}<DropdownMenuSeparator /><DropdownMenuItem className="text-destructive" onSelect={async () => { await api(`/api/v1/workspaces/${wsId}/members/${m.userId}`, { method: "DELETE" }); void load(); }}><Trash2 />移出工作区</DropdownMenuItem></DropdownMenuContent></DropdownMenu>}</div>)}</div></PageShell>;
}

function InvitePage() { const { token } = useParams(); const nav = useNavigate(); const me = useMe(); const [data, setData] = useState<{ workspace: string; role: string; expiresAt: string } | null>(null); const [err, setErr] = useState(""); useEffect(() => { api<typeof data>(`/api/v1/invites/${token}`).then(setData).catch(e => setErr((e as Error).message)); }, [token]); return <PublicFrame>{err ? <Empty icon={<Link2 />} title="邀请已失效" text={err} /> : !data ? <div className="grid place-items-center py-20"><Circle className="animate-pulse fill-current" /></div> : <div className="mx-auto max-w-md rounded-2xl border p-8 text-center"><Users className="mx-auto size-10 text-muted-foreground" /><h1 className="mt-5 text-2xl font-semibold">加入 {data.workspace}</h1><p className="mt-2 text-sm text-muted-foreground">你将以 {data.role} 身份加入此工作区。</p>{me === null ? <Button className="mt-6" onClick={() => location.assign(`/login?redirect=/invite/${token}`)}>登录后加入</Button> : <Button className="mt-6" onClick={async () => { const d = await api<{ workspaceId: string }>(`/api/v1/invites/${token}/accept`, { method: "POST" }); nav(`/w/${d.workspaceId}`); }}>确认加入</Button>}</div>}</PublicFrame>; }

function AdminPage() { const nav = useNavigate(); const [overview, setOverview] = useState<{ userCount: number; workspaceCount: number; settings: Record<string, boolean | number> } | null>(null); const [usersList, setUsers] = useState<Array<{ id: string; displayName: string; email: string; handle: string; roleInstance: string; status: string }>>([]); const [codes, setCodes] = useState<Array<{ id: string; prefix: string; usedCount: number; maxUses: number; status: string; note?: string }>>([]); const [newCodes, setNewCodes] = useState<string[]>([]);
  const load = async () => { const [o,u,c] = await Promise.all([api<typeof overview>("/api/v1/admin/overview"),api<{users:typeof usersList}>("/api/v1/admin/users"),api<{codes:typeof codes}>("/api/v1/admin/registration-codes")]); setOverview(o); setUsers(u.users); setCodes(c.codes); }; useEffect(() => { void load(); }, []);
  const setting = async (key: string, value: boolean) => { await api("/api/v1/admin/settings", { method: "PATCH", body: JSON.stringify({ [key]: value }) }); void load(); };
  return <PageShell title="实例后台" subtitle="管理注册策略、注册码和实例用户。" back={() => nav("/app")}><Tabs.Root defaultValue="overview"><Tabs.List className="mb-6 inline-flex rounded-lg bg-muted p-1">{[["overview","概览"],["registration","注册策略"],["codes","注册码"],["users","用户"]].map(([v,t]) => <Tabs.Trigger key={v} value={v} className="rounded-md px-4 py-2 text-sm data-[state=active]:bg-background data-[state=active]:shadow-sm">{t}</Tabs.Trigger>)}</Tabs.List><Tabs.Content value="overview"><div className="grid gap-4 sm:grid-cols-2"><div className="rounded-xl border bg-background p-5"><p className="text-sm text-muted-foreground">用户</p><p className="mt-2 text-3xl font-semibold">{overview?.userCount ?? 0}</p></div><div className="rounded-xl border bg-background p-5"><p className="text-sm text-muted-foreground">工作区</p><p className="mt-2 text-3xl font-semibold">{overview?.workspaceCount ?? 0}</p></div></div></Tabs.Content><Tabs.Content value="registration"><div className="rounded-xl border bg-background">{[["allowOpenRegistration","开放注册"],["allowCodeRegistration","允许注册码"],["allowUserCreateWorkspace","允许用户创建工作区"],["squareEnabled","开启广场"],["aiEnabled","开启 AI"]].map(([k,t],i) => <label key={k} className={cn("flex items-center gap-4 p-4",i&&"border-t")}><span className="flex-1 text-sm font-medium">{t}</span><input type="checkbox" checked={!!overview?.settings?.[k]} onChange={e => void setting(k,e.target.checked)} /></label>)}<div className="flex items-center gap-4 border-t p-4"><span className="flex-1"><b className="block text-sm">默认用户存储容量</b><small className="text-muted-foreground">新用户和未设置单独覆盖的用户使用此限制，默认 1GB。</small></span><select className="h-9 rounded-lg border bg-background px-3 text-sm" value={Number(overview?.settings?.defaultUserStorageBytes??1073741824)} onChange={e=>void api('/api/v1/admin/settings',{method:'PATCH',body:JSON.stringify({defaultUserStorageBytes:Number(e.target.value)})}).then(load)}><option value={536870912}>512 MB</option><option value={1073741824}>1 GB</option><option value={2147483648}>2 GB</option><option value={5368709120}>5 GB</option><option value={10737418240}>10 GB</option></select></div></div></Tabs.Content><Tabs.Content value="codes"><Button className="mb-4" onClick={async () => { const d=await api<{codes:string[]}>("/api/v1/admin/registration-codes",{method:"POST",body:JSON.stringify({quantity:5,maxUses:1,expiresInDays:30,note:"后台生成"})});setNewCodes(d.codes);void load(); }}><Plus />生成 5 个注册码</Button>{newCodes.length>0&&<div className="mb-4 rounded-xl border border-primary/20 bg-primary/5 p-4"><p className="mb-2 text-sm font-medium">仅本次显示，请立即保存：</p>{newCodes.map(c=><code key={c} className="block py-1 text-sm">{c}</code>)}</div>}<div className="rounded-xl border bg-background">{codes.map((c,i)=><div key={c.id} className={cn("flex items-center gap-3 p-4",i&&"border-t")}><code className="flex-1">{c.prefix}…</code><span className="text-xs text-muted-foreground">{c.usedCount}/{c.maxUses}</span><Badge>{c.status}</Badge><Button variant="ghost" size="icon" onClick={async()=>{await api(`/api/v1/admin/registration-codes/${c.id}`,{method:"DELETE"});void load();}}><Trash2 /></Button></div>)}</div></Tabs.Content><Tabs.Content value="users"><div className="rounded-xl border bg-background">{usersList.map((u,i)=><div key={u.id} className={cn("flex items-center gap-4 p-4",i&&"border-t")}><div className="min-w-0 flex-1"><p className="text-sm font-medium">{u.displayName} @{u.handle}</p><p className="text-xs text-muted-foreground">{u.email}</p></div><Badge>{u.roleInstance}</Badge><Badge>{u.status}</Badge><DropdownMenu><DropdownMenuTrigger asChild><Button variant="ghost" size="icon"><MoreHorizontal /></Button></DropdownMenuTrigger><DropdownMenuContent align="end"><DropdownMenuItem onSelect={async()=>{await api(`/api/v1/admin/users/${u.id}`,{method:"PATCH",body:JSON.stringify({roleInstance:u.roleInstance==="admin"?"user":"admin"})});void load();}}>{u.roleInstance==="admin"?"降为普通用户":"提升为管理员"}</DropdownMenuItem><DropdownMenuItem className="text-destructive" onSelect={async()=>{await api(`/api/v1/admin/users/${u.id}`,{method:"PATCH",body:JSON.stringify({status:u.status==="banned"?"active":"banned"})});void load();}}>{u.status==="banned"?"解除封禁":"封禁并踢出会话"}</DropdownMenuItem></DropdownMenuContent></DropdownMenu></div>)}</div></Tabs.Content></Tabs.Root></PageShell>; }

function Trash(){const{wsId}=useParams();const nav=useNavigate();type Item={id:string;title:string;trashedAt:string};const[data,setData]=useState<{notes:Item[];folders:Item[];notebooks:Item[]}>({notes:[],folders:[],notebooks:[]});const load=()=>wsId&&api<typeof data>(`/api/v1/workspaces/${wsId}/trash`).then(setData);useEffect(()=>{void load()},[wsId]);const groups:[string,"note"|"folder"|"notebook",Item[]][]=[["笔记","note",data.notes],["目录","folder",data.folders],["笔记本","notebook",data.notebooks]];return <PageShell title="回收站" subtitle="内容保留 30 天；恢复目录或笔记本时会恢复同一删除批次的子内容。" back={()=>nav(`/w/${wsId}`)}><div className="space-y-5">{groups.map(([label,type,items])=>items.length>0&&<section key={type} className="overflow-hidden rounded-xl border"><h2 className="bg-muted/40 px-4 py-3 text-sm font-semibold">{label}</h2>{items.map((n,i)=><div key={n.id} className={cn("flex items-center gap-4 p-4",i&&"border-t")}><span className="grid size-10 place-items-center rounded-lg bg-muted"><Trash2 className="size-4"/></span><div className="flex-1"><p className="text-sm font-medium">{n.title}</p><p className="text-xs text-muted-foreground">删除于 {new Date(n.trashedAt).toLocaleString()}</p></div><Button variant="outline" size="sm" onClick={async()=>{await api(`/api/v1/trash/${type}/${n.id}/restore`,{method:"POST"});void load()}}><RotateCcw/>恢复</Button></div>)}</section>)}{!data.notes.length&&!data.folders.length&&!data.notebooks.length&&<Empty icon={<Archive/>} title="回收站是空的" text="删除的笔记、目录和笔记本会出现在这里。"/>}</div></PageShell>;}

function PageShell({ title, subtitle, back, children }: { title: string; subtitle: string; back: () => void; children: ReactNode }) { return <div className="min-h-full bg-muted/25"><header className="flex h-14 items-center border-b border-border bg-background px-4"><Button variant="ghost" onClick={back}><ChevronRight className="rotate-180" />返回工作区</Button><div className="ml-auto"><Brand /></div></header><main className="mx-auto max-w-4xl px-5 py-10"><h1 className="text-3xl font-semibold tracking-[-.045em]">{title}</h1><p className="mt-2 text-sm text-muted-foreground">{subtitle}</p><div className="mt-8">{children}</div></main></div>; }
function Empty({ icon, title, text }: { icon: ReactNode; title: string; text: string }) { return <div className="py-20 text-center"><span className="mx-auto grid size-12 place-items-center rounded-xl bg-muted text-muted-foreground">{icon}</span><p className="mt-4 text-sm font-medium">{title}</p><p className="mt-1 text-xs text-muted-foreground">{text}</p></div>; }

function Integrations() { const nav=useNavigate(); const q=new URLSearchParams(location.search); const workspaceId=q.get("workspace")??""; const [providers,setProviders]=useState<Array<{id:string;baseUrl:string;chatModel:string;keySuffix:string}>>([]); const [tokens,setTokens]=useState<Array<{id:string;name:string;rw:string;status:string;lastUsedAt:string|null}>>([]); const [provider,setProvider]=useState({baseUrl:"https://api.openai.com/v1",chatModel:"gpt-4o-mini",apiKey:""}); const [secret,setSecret]=useState("");const[mcpLimit,setMcpLimit]=useState(10485760);const load=async()=>{if(workspaceId){const p=await api<{providers:typeof providers}>(`/api/v1/workspaces/${workspaceId}/ai/provider`);setProviders(p.providers)}const t=await api<{tokens:typeof tokens}>("/api/v1/mcp/tokens");setTokens(t.tokens)};useEffect(()=>{void load()},[workspaceId]);return <PageShell title="AI 与 MCP" subtitle="配置 OpenAI 兼容模型，并为外部 Agent 创建受限钥匙。" back={()=>nav("/app")}><Tabs.Root defaultValue="ai"><Tabs.List className="mb-6 inline-flex rounded-lg bg-muted p-1"><Tabs.Trigger value="ai" className="rounded-md px-4 py-2 text-sm data-[state=active]:bg-background">AI 提供商</Tabs.Trigger><Tabs.Trigger value="mcp" className="rounded-md px-4 py-2 text-sm data-[state=active]:bg-background">MCP 钥匙</Tabs.Trigger></Tabs.List><Tabs.Content value="ai"><div className="rounded-xl border bg-background p-5"><div className="grid gap-3"><Input value={provider.baseUrl} onChange={e=>setProvider({...provider,baseUrl:e.target.value})} placeholder="Base URL"/><Input value={provider.chatModel} onChange={e=>setProvider({...provider,chatModel:e.target.value})} placeholder="模型"/><Input type="password" value={provider.apiKey} onChange={e=>setProvider({...provider,apiKey:e.target.value})} placeholder="API Key"/><Button className="w-fit" onClick={async()=>{await api(`/api/v1/workspaces/${workspaceId}/ai/provider`,{method:"POST",body:JSON.stringify({...provider,personal:false})});setProvider({...provider,apiKey:""});void load()}}>保存工作区配置</Button></div></div><div className="mt-4 space-y-2">{providers.map(p=><div key={p.id} className="flex items-center gap-3 rounded-xl border bg-background p-4"><Bot/><div className="flex-1"><p className="text-sm font-medium">{p.chatModel}</p><p className="text-xs text-muted-foreground">{p.baseUrl} · Key ••••{p.keySuffix}</p></div><Button variant="ghost" size="icon" onClick={async()=>{await api(`/api/v1/ai/providers/${p.id}`,{method:"DELETE"});void load()}}><Trash2/></Button></div>)}</div></Tabs.Content><Tabs.Content value="mcp"><div className="mb-3 flex max-w-md items-center gap-3"><label className="flex-1 text-sm">每日写入上限<Input type="number" min={1} value={Math.round(mcpLimit/1048576)} onChange={e=>setMcpLimit(Math.max(1,Number(e.target.value))*1048576)}/></label><span className="mt-5 text-xs text-muted-foreground">MB / 天</span></div><Button onClick={async()=>{const d=await api<{secret:string}>("/api/v1/mcp/tokens",{method:"POST",body:JSON.stringify({name:"默认 Agent",workspaceId,notebookMode:"inherit",notebookIds:[],rw:"write",allowDelete:false,requireAiIndex:true,allowPrivateNotebooks:false,dailyWriteLimitBytes:mcpLimit})});setSecret(d.secret);void load()}}><Plus/>创建写作钥匙</Button>{secret&&<div className="mt-4 rounded-xl border border-primary/20 bg-primary/5 p-4"><p className="text-sm font-medium">明文只显示这一次</p><code className="mt-2 block break-all text-sm">{secret}</code><Button className="mt-3" size="sm" onClick={()=>navigator.clipboard.writeText(secret)}><Copy/>复制</Button></div>}<div className="mt-4 space-y-2">{tokens.map(t=><div key={t.id} className="flex items-center gap-3 rounded-xl border bg-background p-4"><Link2/><div className="flex-1"><p className="text-sm font-medium">{t.name}</p><p className="text-xs text-muted-foreground">{t.rw} · {t.status}</p></div><Button variant="outline" size="sm" onClick={async()=>{const d=await api<{secret:string}>(`/api/v1/mcp/tokens/${t.id}/rotate`,{method:"POST"});setSecret(d.secret);void load()}}><RotateCcw/>轮换</Button><Button variant="ghost" size="icon" onClick={async()=>{await api(`/api/v1/mcp/tokens/${t.id}`,{method:"DELETE"});void load()}}><Trash2/></Button></div>)}</div></Tabs.Content></Tabs.Root></PageShell>; }

function Appearance() {
  const { refresh } = useThemeRefresh(); const nav = useNavigate(); const [me, setMe] = useState<Me | null>(null); const [themes, setThemes] = useState<{ id: string; name: string; author?: string }[]>([]); const [accent, setAccent] = useState("#111111"); const [raw, setRaw] = useState(""); const [msg, setMsg] = useState("");
  useEffect(() => { api<Me>("/api/v1/me").then(m => { setMe(m); setAccent(m.accent ?? "#111111"); }); api<{ themes: typeof themes }>("/api/v1/themes").then(d => setThemes(d.themes)); }, []);
  async function patch(p: Partial<{ appearance: Me["appearance"]; themeId: string; accent: string | null }>) { await api("/api/v1/me/appearance", { method: "PATCH", body: JSON.stringify(p) }); refresh(); }
  const colors = ["#111111", "#52525b", "#2563eb", "#7c3aed", "#0f766e", "#c2410c"];
  return <PageShell title="外观" subtitle="选择明暗模式、强调色和已安装的主题包。" back={() => nav("/app")}><div className="space-y-8"><section><h2 className="text-sm font-semibold">显示模式</h2><p className="mt-1 text-xs text-muted-foreground">跟随操作系统，或固定为浅色、深色。</p><div className="mt-4 grid grid-cols-3 gap-3">{(["system", "light", "dark"] as const).map(mode => <button key={mode} onClick={() => { setMe(me && { ...me, appearance: mode }); void patch({ appearance: mode }); }} className={cn("rounded-xl border p-3 text-left transition hover:border-foreground/30", me?.appearance === mode && "border-primary ring-2 ring-primary/10")}><div className={cn("mb-3 h-20 rounded-lg border p-2", mode === "dark" ? "bg-zinc-900" : mode === "light" ? "bg-white" : "bg-gradient-to-r from-white to-zinc-900")}><div className="h-2 w-1/2 rounded bg-zinc-400/40" /><div className="mt-2 h-8 rounded border border-zinc-400/20" /></div><span className="text-sm font-medium">{mode === "system" ? "跟随系统" : mode === "light" ? "浅色" : "深色"}</span></button>)}</div></section><Separator /><section><h2 className="text-sm font-semibold">强调色</h2><p className="mt-1 text-xs text-muted-foreground">用于按钮、链接和选中状态。</p><div className="mt-4 flex items-center gap-3">{colors.map(c => <button key={c} aria-label={c} onClick={() => { setAccent(c); void patch({ accent: c }); }} className={cn("size-8 rounded-full border-2 border-background shadow-sm ring-offset-2", accent === c && "ring-2 ring-foreground")} style={{ backgroundColor: c }} />)}<label className="relative grid size-8 cursor-pointer place-items-center rounded-full border border-dashed border-border"><Plus className="size-3.5" /><input className="absolute inset-0 opacity-0" type="color" value={accent} onChange={e => { setAccent(e.target.value); void patch({ accent: e.target.value }); }} /></label></div></section><Separator /><section><h2 className="text-sm font-semibold">主题包</h2><p className="mt-1 text-xs text-muted-foreground">主题包只能定义安全的 JSON 设计令牌。</p><div className="mt-4 grid gap-3 sm:grid-cols-2">{themes.map(t => <button key={t.id} onClick={() => { setMe(me && { ...me, themeId: t.id }); void patch({ themeId: t.id }); }} className={cn("flex items-center gap-3 rounded-xl border p-4 text-left hover:bg-muted/50", me?.themeId === t.id && "border-primary ring-2 ring-primary/10")}><span className="grid size-10 place-items-center rounded-lg bg-foreground text-background"><Paintbrush className="size-4" /></span><span><b className="block text-sm">{t.name}</b><small className="text-muted-foreground">{t.author ?? "本地主题"}</small></span>{me?.themeId === t.id && <Check className="ml-auto" />}</button>)}</div><details className="mt-4 rounded-xl border border-border p-4"><summary className="cursor-pointer text-sm font-medium">导入 theme.json</summary><div className="mt-4 space-y-3"><Textarea className="min-h-40 font-mono text-xs" value={raw} onChange={e => setRaw(e.target.value)} placeholder="粘贴主题 JSON…" /><Button size="sm" onClick={async () => { try { await api("/api/v1/themes/import", { method: "POST", body: JSON.stringify(JSON.parse(raw)) }); const d = await api<{ themes: typeof themes }>("/api/v1/themes"); setThemes(d.themes); setMsg("主题已安装"); } catch (x) { setMsg((x as Error).message); } }}>导入主题</Button>{msg && <span className="ml-3 text-xs text-muted-foreground">{msg}</span>}</div></details></section></div></PageShell>;
}

type FeedPost={id:string;body:string;createdAt:string;author:{handle:string;displayName:string}|null;note:{id:string;title:string}|null;likes:number;liked:boolean};
function Square() { const me=useMe(); const [posts,setPosts]=useState<FeedPost[]>([]); const [body,setBody]=useState(""); const load=()=>api<{posts:FeedPost[]}>("/api/v1/feed/public").then(d=>setPosts(d.posts)); useEffect(()=>{void load()},[]); return <div className="min-h-full bg-muted/25"><header className="sticky top-0 z-20 flex h-14 items-center border-b bg-background/90 px-5 backdrop-blur"><Brand /><nav className="ml-8 flex gap-1"><Button variant="secondary" size="sm">广场</Button><Button variant="ghost" size="sm" onClick={() => location.assign("/app")}>我的知识库</Button></nav>{me&&<Avatar.Root className="ml-auto grid size-8 place-items-center rounded-full bg-foreground text-xs text-background"><Avatar.Fallback>{me.displayName.slice(0,1)}</Avatar.Fallback></Avatar.Root>}</header><main className="mx-auto max-w-2xl px-4 py-6">{me&&<form className="mb-4 rounded-2xl border bg-background p-4 shadow-sm" onSubmit={async e=>{e.preventDefault();if(!body.trim())return;await api("/api/v1/posts",{method:"POST",body:JSON.stringify({body,visibility:"public"})});setBody("");void load()}}><Textarea className="min-h-20 resize-none border-0 p-0 shadow-none focus-visible:ring-0" value={body} onChange={e=>setBody(e.target.value)} placeholder="分享一个想法或公开知识…" maxLength={5000}/><div className="mt-3 flex justify-end border-t pt-3"><Button size="sm" disabled={!body.trim()}>发布到广场</Button></div></form>}<div className="space-y-3">{posts.length===0?<Empty icon={<LayoutGrid/>} title="广场还没有动态" text="发布第一条公开动态吧。"/>:posts.map(p=><article key={p.id} className="rounded-2xl border bg-background p-5 shadow-sm"><div className="flex items-center gap-3"><Avatar.Root className="grid size-10 place-items-center rounded-full bg-foreground text-background"><Avatar.Fallback>{p.author?.displayName.slice(0,1)??"?"}</Avatar.Fallback></Avatar.Root><div><p className="text-sm font-medium">{p.author?.displayName??"已注销用户"} <span className="font-normal text-muted-foreground">@{p.author?.handle}</span></p><p className="text-xs text-muted-foreground">{new Date(p.createdAt).toLocaleString()}</p></div></div><p className="mt-4 whitespace-pre-wrap text-[15px] leading-7">{p.body}</p>{p.note&&<div className="mt-4 rounded-xl border bg-muted/30 p-4"><BookOpen className="mb-2 size-4 text-muted-foreground"/><p className="font-medium">{p.note.title}</p></div>}<div className="mt-4 flex border-t pt-3"><Button variant="ghost" size="sm" disabled={!me} onClick={async()=>{await api(`/api/v1/posts/${p.id}/like`,{method:"POST"});void load()}} className={p.liked?"text-destructive":"text-muted-foreground"}>♥ {p.likes}</Button></div></article>)}</div></main></div>; }

function Manage() { const { wsId } = useParams(); const nav = useNavigate(); const [ws, setWs] = useState<Ws | null>(null); const load = () => api<{ workspaces: Ws[] }>("/api/v1/workspaces").then(d => setWs(d.workspaces.find(x => x.id === wsId) ?? null)); useEffect(() => { void load(); }, [wsId]); if (!wsId) return null;
  const tab = "rounded-md px-4 py-2 text-sm data-[state=active]:bg-background";
  return <PageShell title="备份与审计" subtitle={`${ws?.name ?? "工作区"}${ws?.frozen ? " · 已冻结，当前只读" : ""}。备份、导出、审计与冻结都只有工作区管理员能操作。`} back={() => nav(`/w/${wsId}`)}>
    <Tabs.Root defaultValue="backup"><Tabs.List className="mb-6 inline-flex rounded-lg bg-muted p-1"><Tabs.Trigger value="backup" className={tab}>备份</Tabs.Trigger><Tabs.Trigger value="transfer" className={tab}>导出与恢复</Tabs.Trigger><Tabs.Trigger value="audit" className={tab}>审计日志</Tabs.Trigger><Tabs.Trigger value="danger" className={tab}>冻结</Tabs.Trigger></Tabs.List>
      <Tabs.Content value="backup"><BackupPanel workspaceId={wsId} /></Tabs.Content>
      <Tabs.Content value="transfer"><TransferPanel workspaceId={wsId} workspaceName={ws?.name ?? "工作区"} /></Tabs.Content>
      <Tabs.Content value="audit"><AuditPanel workspaceId={wsId} /></Tabs.Content>
      <Tabs.Content value="danger"><DangerPanel workspaceId={wsId} frozen={ws?.frozen ?? false} onChanged={() => void load()} /></Tabs.Content>
    </Tabs.Root></PageShell>;
}

export function App() { const me = useMe(); return <Routes><Route path="/" element={<Square />} /><Route path="/login" element={<Login />} /><Route path="/register" element={<Register />} /><Route path="/forgot-password" element={<ForgotPassword />} /><Route path="/reset-password" element={<ResetPassword />} /><Route path="/verify-email" element={<VerifyEmail />} /><Route path="/app" element={me === undefined ? null : me === null ? <Navigate to="/login" replace /> : me.personalWorkspaceId ? <Navigate to={`/w/${me.personalWorkspaceId}`} replace /> : <Navigate to="/login" />} /><Route path="/w/:wsId" element={<Workspace />} /><Route path="/w/:wsId/n/:noteId" element={<Workspace />} /><Route path="/w/:wsId/trash" element={<Trash />} /><Route path="/w/:wsId/members" element={<Members />} /><Route path="/w/:wsId/manage" element={<Manage />} /><Route path="/invite/:token" element={<InvitePage />} /><Route path="/admin" element={<AdminPage />} /><Route path="/p/:token" element={<PublicShare />} /><Route path="/s/:wsSlug/:nbSlug" element={<PublicSite />} /><Route path="/settings/integrations" element={<Integrations />} /><Route path="/settings/appearance" element={<Appearance />} /></Routes>; }
